// Read-only operational metadata projection. Never an adjudication ledger or source archive.
export const WORKLIST_SCHEMA='ocr.source-worklist.v1',MAX_WORKLIST_BYTES=25*1024*1024,MAX_WORKLIST_ROWS=20000;
const need=(ok,m)=>{if(!ok)throw Error(m);};
const exact=(o,keys)=>need(o&&typeof o==='object'&&!Array.isArray(o)&&Object.keys(o).sort().join(',')===[...keys].sort().join(','),'Unexpected worklist fields');
function text(v,n,nullable=false){need(nullable&&v===null||typeof v==='string'&&v.trim()&&v.length<=n,'Missing or oversized metadata');}
export function validateWorklist(w){exact(w,['schema','scope','rows']);need(w.schema===WORKLIST_SCHEMA&&w.scope==='private-review-only','Use the private review metadata format');need(Array.isArray(w.rows)&&w.rows.length<=MAX_WORKLIST_ROWS,'Worklist exceeds 20000 metadata rows');const ids=new Set();for(const r of w.rows){exact(r,['id','sourceGroup','publisher','downloadHost','kind','filename','url','archiveItem','sha256','locator','status','problemSummary','versionReference','attemptedAt','evidenceSource','nextCheck','bucket','possessionBasis']);text(r.id,2500);need(!ids.has(r.id),'Duplicate worklist ID');ids.add(r.id);text(r.sourceGroup,600);text(r.publisher,500,true);text(r.downloadHost,300,true);need(['source-review-occurrence','acquisition-review','sourcing-review','integrity-review','status-unknown','ocr-quality-report'].includes(r.kind),'Unknown review type');text(r.filename,1000,true);text(r.archiveItem,300,true);text(r.locator,2000,true);text(r.status,200);text(r.problemSummary,1000);text(r.versionReference,500,true);text(r.attemptedAt,100,true);text(r.evidenceSource,2000);text(r.nextCheck,1000);need(['held-review-confirmed','expected-acquisition-unresolved','needs-reconciliation'].includes(r.bucket),'Unknown possession/review bucket');text(r.possessionBasis,1000);need(r.sha256===null||typeof r.sha256==='string'&&/^[a-f0-9]{64}$/.test(r.sha256),'Invalid source hash');if(r.url!==null){text(r.url,2048);const u=new URL(r.url);need(u.protocol==='https:'&&!u.username&&!u.password,'Use HTTPS references without credentials; destinations are not verified');}}need(new TextEncoder().encode(JSON.stringify(w)).length<=MAX_WORKLIST_BYTES,'Worklist exceeds 25 MiB');return w;}
export function importWorklist(raw){need(typeof raw==='string'&&new TextEncoder().encode(raw).length<=MAX_WORKLIST_BYTES,'Choose metadata under 25 MiB, never a source document');return validateWorklist(JSON.parse(raw));}
export function sourceGroups(w){const counts=new Map();for(const r of w.rows)counts.set(r.sourceGroup,(counts.get(r.sourceGroup)||0)+1);return [...counts].sort((a,b)=>a[0].localeCompare(b[0]));}
export function worklistPage(w,{source='all',kind='all',bucket='all',query='',page=0,pageSize=50}={}){need(Number.isInteger(page)&&page>=0&&Number.isInteger(pageSize)&&pageSize>=1&&pageSize<=100,'Invalid page bounds');const q=query.trim().toLowerCase();const selected=w.rows.filter(r=>(source==='all'||r.sourceGroup===source)&&(kind==='all'||r.kind===kind)&&(bucket==='all'||r.bucket===bucket)&&(!q||[r.filename,r.archiveItem,r.problemSummary,r.publisher].some(v=>v?.toLowerCase().includes(q)))).sort((a,b)=>a.sourceGroup.localeCompare(b.sourceGroup)||(a.filename||'').localeCompare(b.filename||'')||a.id.localeCompare(b.id));const pages=Math.max(1,Math.ceil(selected.length/pageSize)),index=Math.min(page,pages-1);return {total:selected.length,pages,page:index,rows:selected.slice(index*pageSize,(index+1)*pageSize)};}

// A gap listing is evidence to inspect, not an invitation to retry a file.
export const acquisitionGap = row => row.bucket === "expected-acquisition-unresolved" || ["acquisition-review","sourcing-review","integrity-review","status-unknown"].includes(row.kind);
